#!/bin/sh
# Runs once, inside the new root (chroot), right after debootstrap --second-stage.
# Called by the initramfs (work/nas/stage1-root.sh). No network is needed here.
set -e

echo mrg5-nas > /etc/hostname
cat > /etc/hosts <<'EOF'
127.0.0.1	localhost
127.0.1.1	mrg5-nas
::1		localhost ip6-localhost ip6-loopback
EOF

cat > /etc/fstab <<'EOF'
LABEL=MRG5ROOT	/	ext4	defaults,noatime,errors=remount-ro	0	1
EOF

cat > /etc/apt/sources.list <<'EOF'
deb http://deb.debian.org/debian bookworm main contrib non-free-firmware
deb http://deb.debian.org/debian bookworm-updates main contrib non-free-firmware
deb http://deb.debian.org/debian-security bookworm-security main contrib non-free-firmware
EOF

# Network: DHCP only on eth0. Only the rescue initramfs keeps the fixed
# 192.168.3.60 fallback.
mkdir -p /etc/systemd/network
cat > /etc/systemd/network/10-eth0.network <<'EOF'
[Match]
Name=eth0

[Network]
DHCP=yes
DNS=1.1.1.1 9.9.9.9

[DHCPv4]
UseDNS=no
EOF
systemctl enable systemd-networkd systemd-resolved systemd-timesyncd ssh
ln -sf /run/systemd/resolve/stub-resolv.conf /etc/resolv.conf

# SSH: key-only root login, same key as the rescue initramfs.
install -d -m 700 /root/.ssh
install -m 600 /mrg5/authorized_keys /root/.ssh/authorized_keys
sed -i 's/^#\?PasswordAuthentication.*/PasswordAuthentication no/' /etc/ssh/sshd_config
# Host keys are generated by the second stage; regenerate if any is missing.
ssh-keygen -A

# Locale
sed -i 's/^# *\(en_US.UTF-8\)/\1/' /etc/locale.gen
locale-gen
echo 'LANG=C.UTF-8' > /etc/default/locale

# Compressed swap in RAM, 25 % of memory. zram is built into the kernel (no modules), so
# Debian's zramswap, which runs modprobe, cannot be used; configure the device directly.
cat > /etc/systemd/system/mrg5-zram.service <<'EOF'
[Unit]
Description=Compressed swap in RAM (zram is built into the kernel)
DefaultDependencies=no
Before=swap.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/sh -c "(grep -qw zstd /sys/block/zram0/comp_algorithm && echo zstd > /sys/block/zram0/comp_algorithm; true) && awk \"/MemTotal/ {print \\$2 * 1024 / 4}\" /proc/meminfo > /sys/block/zram0/disksize && mkswap /dev/zram0 && swapon -p 100 /dev/zram0"
ExecStop=/bin/sh -c "swapoff /dev/zram0; echo 1 > /sys/block/zram0/reset"

[Install]
WantedBy=swap.target
EOF
systemctl enable mrg5-zram

# Grow the filesystem to fill its partition on the first real boot.
cat > /etc/systemd/system/mrg5-growfs.service <<'EOF'
[Unit]
Description=Grow the root filesystem to its partition
ConditionPathExists=/mrg5/growfs

[Service]
Type=oneshot
ExecStart=/bin/sh -c 'resize2fs "$(findmnt -no SOURCE /)" && rm -f /mrg5/growfs'

[Install]
WantedBy=multi-user.target
EOF
touch /mrg5/growfs
systemctl enable mrg5-growfs

rm -f /mrg5/authorized_keys
touch /mrg5/installed
echo "MRG5 firstboot configuration done"
